//! Symmetry: deck generators + fundamental domain, declare, and the two-phase cut-and-keep-chamber.
//!
//! The model's topology **is** the fundamental domain `F`; the deck group is generated by the
//! deck boundaries ([`Symmetry::generators`]). The full model is `union g F`, derived by
//! [`crate::unfold`] as a view.
//!
//! Cutting is a topology operation, so this layer only plans and records it:
//! [`plan_cut`] (pure) says which half-spaces to keep; the topology kernel executes the cut and
//! returns a [`CutOutcome`] (data in, data out); [`Model::apply_cut`] verifies the outcome against
//! the plan, re-keys every table through the lineage, tags the caps as deck faces and records the
//! generator. After a cut the generators are exactly the decks produced by cuts or declarations.

use crate::boundary::{BoundaryKind, Deck, DeckSide};
use crate::detect::Verification;
use crate::error::{ModelError, Result, expect_kind};
use crate::model::Model;
use crate::xf::{Bins, GROUP_TOL, GeomCache, Plane, Tolerance, TransformIndex, face_shape_close, transform_face_moments, transforms_close, vec_of, vector_area_sign};
use sm_core::{EntityId, EntityKind, Point3, Transform, Vector3};
use sm_topo_api::{CutOutcome, Dim, FaceClass, TopologyView, TopologyViewExt};
use smallvec::SmallVec;
use std::collections::BTreeSet;

/// Element budget of a finite point group.
pub const MAX_GROUP_ORDER: usize = 4096;

/// Which side a cut keeps.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
pub enum Keep {
    /// The side the plane normal points to (translation: the slab starts at `origin` and runs
    /// along the vector; rotation: the wedge runs counter-clockwise from the start direction).
    Positive,
    /// The opposite side (translation: the slab ends at `origin`; rotation: clockwise).
    Negative,
}

/// A cut-and-keep request: the deck the new cap faces get, and where the chamber is.
#[derive(Clone, Copy, Debug, PartialEq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
pub struct CutSpec {
    /// The deck of the cut: a mirror plane, a translation (slab) or a rotation (wedge).
    pub deck: Deck,
    /// Which side to keep.
    pub keep: Keep,
    /// Mirror: unused. Translation: the slab base. Rotation: a point defining the start
    /// half-plane (with the axis).
    pub origin: Point3,
}

/// The geometry the kernel must produce, derived purely from a [`CutSpec`].
#[derive(Clone, Debug, PartialEq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
pub struct CutPlan {
    /// Half-spaces whose intersection is the kept chamber. Each plane's normal points **into**
    /// the kept region (kept: `n . x >= offset`).
    pub half_spaces: SmallVec<[Plane; 2]>,
    /// Deck side of the cap on each half-space plane (same order): `SelfPaired` for a mirror,
    /// `A` then `B` for slab and wedge.
    pub roles: SmallVec<[DeckSide; 2]>,
    /// The request.
    pub spec: CutSpec,
}

/// Plan a cut. Mirror: one half-space. Translation: a slab of thickness `|vector|`. Rotation: a
/// wedge of angle `2 pi num/den`, which must be below a half turn.
pub fn plan_cut(spec: &CutSpec) -> Result<CutPlan> {
    spec.deck.check()?;
    let mut half_spaces: SmallVec<[Plane; 2]> = SmallVec::new();
    let mut roles: SmallVec<[DeckSide; 2]> = SmallVec::new();
    match spec.deck {
        Deck::Mirror { plane } => {
            half_spaces.push(if spec.keep == Keep::Positive { plane } else { plane.flipped() });
            roles.push(DeckSide::SelfPaired);
        }
        Deck::Translation { vector } => {
            let len = vector.norm();
            let u = vector * (1.0 / len);
            let base = if spec.keep == Keep::Positive { vec_of(spec.origin) } else { vec_of(spec.origin) - vector };
            half_spaces.push(Plane::new(u, u.dot(base))?);
            half_spaces.push(Plane::new(-u, -(u.dot(base) + len))?);
            roles.extend([DeckSide::A, DeckSide::B]);
        }
        Deck::Rotation { axis, angle } => {
            if angle.num * 2 >= angle.den as i32 {
                return Err(ModelError::Invalid("a wedge must span less than half a turn".into()));
            }
            let a = axis.dir;
            let r = spec.origin - axis.point;
            let perp = r - a * a.dot(r);
            if perp.norm() <= 1e-12 * (1.0 + r.norm()) {
                return Err(ModelError::Invalid("wedge start point lies on the axis".into()));
            }
            let u = perp * (1.0 / perp.norm());
            let w = a.cross(u);
            let th = angle.radians();
            let (s, c) = th.sin_cos();
            // Start direction and its in-plane perpendicular.
            let (u0, w0) = if spec.keep == Keep::Positive { (u, w) } else { (u * c - w * s, u * s + w * c) };
            let cv = vec_of(axis.point);
            half_spaces.push(Plane::new(w0, w0.dot(cv))?);
            let w_end = u0 * (-s) + w0 * c;
            half_spaces.push(Plane::new(-w_end, -w_end.dot(cv))?);
            roles.extend([DeckSide::A, DeckSide::B]);
        }
    }
    Ok(CutPlan { half_spaces, roles, spec: *spec })
}

/// The symmetry record (at most one per model).
#[derive(Clone, Debug, PartialEq, Default)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
pub struct Symmetry {
    /// Generators: `Boundary` ids whose kind is a deck, in declaration order.
    pub generators: Vec<EntityId>,
    /// The fundamental domain: its `TopoVolume`s.
    pub domain: BTreeSet<EntityId>,
}

/// How a symmetry statement entered the model. The log is append-only.
#[derive(Clone, Debug, PartialEq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
pub enum Provenance {
    /// Stated by the user.
    Declared,
    /// Stated by an importer (existing faces tagged as deck boundaries).
    Imported,
    /// Accepted from detection, with the verification it had.
    Detected(Verification),
    /// Produced by [`Model::apply_cut`].
    Cut {
        /// The request.
        spec: CutSpec,
    },
}

/// Closure of `gens` under composition (breadth-first, deterministic order, element 0 is the
/// identity). Elements are identified within [`GROUP_TOL`] through a quantized index. Fails with
/// [`ModelError::GroupNotFinite`] when more than `max` elements appear (this is how infinite
/// groups, such as parallel mirrors, are rejected).
pub fn point_group(gens: &[Transform], max: usize) -> Result<Vec<Transform>> {
    let mut elems = vec![Transform::IDENTITY];
    let mut index = TransformIndex::default();
    index.insert(&Transform::IDENTITY, 0);
    let mut head = 0;
    while head < elems.len() {
        let e = elems[head];
        head += 1;
        for g in gens {
            let n = e.compose(g);
            if !n.m.iter().flatten().chain([&n.t.x, &n.t.y, &n.t.z]).all(|v| v.is_finite()) {
                return Err(ModelError::GroupNotFinite { limit: max });
            }
            if index.candidates(&n).iter().any(|&c| transforms_close(&elems[c as usize], &n, GROUP_TOL)) {
                continue;
            }
            if elems.len() >= max {
                return Err(ModelError::GroupNotFinite { limit: max });
            }
            index.insert(&n, elems.len() as u32);
            elems.push(n);
        }
    }
    Ok(elems)
}

/// Match faces of `a` to faces of `b` so that `b = g(a)` as regions with opposed outward normals
/// (`n_B = -g(n_A)`): equal integrated moments of the image, found by spatial binning.
pub(crate) fn pair_by_moments(c: &mut GeomCache<'_>, a: &[EntityId], b: &[EntityId], g: &Transform, tol: &Tolerance) -> core::result::Result<Vec<(EntityId, EntityId)>, String> {
    let l = c.length_scale();
    let bm: Vec<_> = b.iter().map(|f| c.face(*f)).collect();
    let mut bins = Bins::new((1e-3 * l).max(100.0 * tol.linear));
    for (i, m) in bm.iter().enumerate() {
        let m = m.ok_or_else(|| format!("no moments for face {}", b[i]))?;
        if let Some(p) = m.centroid() {
            bins.insert(p, i);
        }
    }
    let mut used = vec![false; b.len()];
    let mut out = Vec::with_capacity(a.len());
    for f in a {
        let m = c.face(*f).ok_or_else(|| format!("no moments for face {f}"))?;
        let img = transform_face_moments(&m, g);
        let p = img.centroid().ok_or_else(|| format!("face {f} has zero area"))?;
        let hit = bins.near(p).into_iter().find(|&i| {
            !used[i] && bm[i].is_some_and(|bmi| face_shape_close(&img, &bmi, l, tol) && vector_area_sign(img.vector_area, bmi.vector_area, img.area, tol) == -1)
        });
        match hit {
            Some(i) => {
                used[i] = true;
                out.push((*f, b[i]));
            }
            None => return Err(format!("face {f} has no mate under the deck transform")),
        }
    }
    if let Some(i) = used.iter().position(|u| !u) {
        return Err(format!("face {} has no mate under the deck transform", b[i]));
    }
    Ok(out)
}

impl Model {
    /// The symmetry record, if any.
    pub fn symmetry(&self) -> Option<&Symmetry> {
        self.symmetry.as_ref()
    }

    /// The append-only provenance log of symmetry statements.
    pub fn provenance(&self) -> &[Provenance] {
        &self.provenance
    }

    /// Declare a symmetry whose generators are existing deck boundaries; the fundamental domain
    /// is every volume of `t`. The point part (mirrors and rotations) must close into a finite
    /// group, else [`ModelError::GroupNotFinite`] (two parallel mirrors compose to a translation:
    /// declare a translation deck with a window instead). Translations are not part of the
    /// closure; their repeat counts are given at unfold time.
    pub fn declare_symmetry(&mut self, gens: &[EntityId], t: &dyn TopologyView) -> Result<()> {
        self.declare_with(gens, t, Provenance::Declared)
    }

    /// Like [`Model::declare_symmetry`], recorded as imported.
    pub fn declare_imported_symmetry(&mut self, gens: &[EntityId], t: &dyn TopologyView) -> Result<()> {
        self.declare_with(gens, t, Provenance::Imported)
    }

    fn declare_with(&mut self, gens: &[EntityId], t: &dyn TopologyView, p: Provenance) -> Result<()> {
        let mut point = Vec::new();
        for (i, g) in gens.iter().enumerate() {
            expect_kind(*g, EntityKind::Boundary)?;
            let row = self.boundaries.get(g).ok_or(ModelError::Unknown(*g))?;
            let Some(d) = row.kind.as_deck() else { return Err(ModelError::Invalid(format!("{g} is not a deck boundary"))) };
            if gens[..i].contains(g) {
                return Err(ModelError::Duplicate(*g));
            }
            if d.order().is_some() {
                point.push(d.transform());
            }
        }
        point_group(&point, MAX_GROUP_ORDER)?;
        self.symmetry = Some(Symmetry { generators: gens.to_vec(), domain: t.cells(Dim::Volume).iter().copied().collect() });
        self.provenance.push(p);
        Ok(())
    }

    /// The lineage of every applied cut, oldest first.
    pub fn cut_lineage(&self) -> &[Vec<sm_topo_api::Lineage>] {
        &self.cuts
    }

    /// Apply the model half of a cut-and-keep-chamber. `out` is what the topology kernel
    /// returned for the `plan`; `t` is the topology **after** the cut and after the discarded
    /// part was removed.
    ///
    /// Transactional. It verifies that every cap lies on a planned plane (using face moments,
    /// `n^T S n = d^2 A`) and that the kept volumes lie in the half-spaces; re-keys all tables
    /// through the lineage (re-pairing deck mates that split, by moments); tags the caps as deck
    /// faces (mirror caps self-paired, slab and wedge caps as A/B pairs found by moments under
    /// the deck transform); applies `cap_color`; adds the generator (reusing an equal existing
    /// deck) and records [`Provenance::Cut`]. Returns the deck boundary of the caps.
    pub fn apply_cut(&mut self, plan: &CutPlan, out: &CutOutcome, cap_color: Option<EntityId>, t: &dyn TopologyView) -> Result<EntityId> {
        let tol = Tolerance::of(t);
        let mut next = self.clone();
        next.apply_lineage(&out.lineage, t)?;
        let mut cache = GeomCache::new(t);
        let l = cache.length_scale();
        let dist_tol = 10.0 * tol.linear + 1e-9 * l;

        // Caps on planned planes.
        let mut by_plane: Vec<Vec<EntityId>> = vec![Vec::new(); plan.half_spaces.len()];
        for cap in &out.caps {
            if t.face_class(cap.face) != Some(FaceClass::Boundary) {
                return Err(ModelError::CutInvalid(format!("cap {} is not a boundary face; remove the discarded part first", cap.face)));
            }
            let fm = cache.face(cap.face).ok_or_else(|| ModelError::CutInvalid(format!("no moments for cap {}", cap.face)))?;
            let (n, d) = fm.plane(tol.linear).ok_or_else(|| ModelError::CutInvalid(format!("cap {} is not planar", cap.face)))?;
            let hit = plan.half_spaces.iter().position(|h| {
                let dot = n.dot(h.normal);
                dot.abs() > 1.0 - 1e-6 && ((if dot > 0.0 { d } else { -d }) - h.offset).abs() <= dist_tol
            });
            match hit {
                Some(i) => by_plane[i].push(cap.face),
                None => return Err(ModelError::CutInvalid(format!("cap {} is off the planned planes", cap.face))),
            }
        }
        // Kept volumes inside the half-spaces.
        let domain: Vec<EntityId> = match &next.symmetry {
            Some(s) => s.domain.iter().copied().collect(),
            None => t.cells(Dim::Volume).to_vec(),
        };
        for v in &domain {
            let m = cache.volume(*v).ok_or_else(|| ModelError::CutInvalid(format!("no moments for volume {v}")))?;
            let c = m.centroid().ok_or_else(|| ModelError::CutInvalid(format!("volume {v} is empty")))?;
            if let Some(h) = plan.half_spaces.iter().find(|h| h.signed_distance(c) < -dist_tol) {
                return Err(ModelError::CutInvalid(format!("volume {v} lies outside the kept half-space (normal {:?})", h.normal)));
            }
        }
        // Tag caps.
        let b = match next.boundaries.values().find(|r| r.kind.as_deck().is_some_and(|d| d.same_as(&plan.spec.deck))) {
            Some(r) => r.id,
            None => {
                let serial = next.boundaries.len() + 1;
                let mut name = format!("cut-{serial}");
                while next.boundaries.values().any(|r| r.name == name) {
                    name.push('+');
                }
                next.add_boundary(&name, BoundaryKind::Deck(plan.spec.deck))?
            }
        };
        let all_caps: Vec<EntityId> = by_plane.iter().flatten().copied().collect();
        if plan.spec.deck.is_self_paired() {
            next.assign_self_paired(b, &all_caps)?;
        } else {
            let g = plan.spec.deck.transform();
            let pairs = pair_by_moments(&mut cache, &by_plane[0], &by_plane[1], &g, &tol).map_err(ModelError::CutInvalid)?;
            next.assign_pairs(b, &pairs)?;
        }
        if let Some(c) = cap_color {
            next.color_faces(c, &all_caps)?;
        }
        match &mut next.symmetry {
            Some(s) => {
                if !s.generators.contains(&b) {
                    s.generators.push(b);
                }
            }
            None => next.symmetry = Some(Symmetry { generators: vec![b], domain: domain.iter().copied().collect() }),
        }
        next.provenance.push(Provenance::Cut { spec: plan.spec });
        next.cuts.push(out.lineage.clone());
        *self = next;
        Ok(b)
    }
}

pub(crate) fn dir_perp_to(d: Vector3) -> Vector3 {
    let e = if d.x.abs() <= d.y.abs() && d.x.abs() <= d.z.abs() {
        Vector3::new(1.0, 0.0, 0.0)
    } else if d.y.abs() <= d.z.abs() {
        Vector3::new(0.0, 1.0, 0.0)
    } else {
        Vector3::new(0.0, 0.0, 1.0)
    };
    let p = e - d * e.dot(d);
    p * (1.0 / p.norm())
}

impl Tolerance {
    /// Tolerances derived from a topology's model tolerance.
    pub fn of(t: &dyn TopologyView) -> Self {
        Self { linear: t.tolerance().linear.max(1e-14), ..Self::default() }
    }
}
